import { connection } from 'next/server'

export default async function ServerTimestamp() {
  await connection()
  const timestamp = new Date().toISOString()

  return (
    <p>
      Server timestamp: <time dateTime={timestamp}>{timestamp}</time>
    </p>
  )
}

